import { afterEach, describe, expect, test } from "bun:test"
import { uuid } from "./uuid"

const cryptoDescriptor = Object.getOwnPropertyDescriptor(globalThis, "crypto")
const secureDescriptor = Object.getOwnPropertyDescriptor(globalThis, "isSecureContext")
const randomDescriptor = Object.getOwnPropertyDescriptor(Math, "random")

const setCrypto = (value: Partial<Crypto>) => {
  Object.defineProperty(globalThis, "crypto", {
    configurable: true,
    value: value as Crypto,
  })
}

const setSecure = (value: boolean) => {
  Object.defineProperty(globalThis, "isSecureContext", {
    configurable: true,
    value,
  })
}

const setRandom = (value: () => number) => {
  Object.defineProperty(Math, "random", {
    configurable: true,
    value,
  })
}

afterEach(() => {
  if (cryptoDescriptor) {
    Object.defineProperty(globalThis, "crypto", cryptoDescriptor)
  }

  if (secureDescriptor) {
    Object.defineProperty(globalThis, "isSecureContext", secureDescriptor)
  }

  if (!secureDescriptor) {
    delete (globalThis as { isSecureContext?: boolean }).isSecureContext
  }

  if (randomDescriptor) {
    Object.defineProperty(Math, "random", randomDescriptor)
  }
})

describe("uuid", () => {
  test("uses randomUUID in secure contexts", () => {
    setCrypto({ randomUUID: () => "00000000-0000-0000-0000-000000000000" })
    setSecure(true)
    expect(uuid()).toBe("00000000-0000-0000-0000-000000000000")
  })

  test("falls back in insecure contexts", () => {
    setCrypto({ randomUUID: () => "00000000-0000-0000-0000-000000000000" })
    setSecure(false)
    setRandom(() => 0.5)
    expect(uuid()).toBe("8")
  })

  test("falls back when randomUUID throws", () => {
    setCrypto({
      randomUUID: () => {
        throw new DOMException("Failed", "OperationError")
      },
    })
    setSecure(true)
    setRandom(() => 0.5)
    expect(uuid()).toBe("8")
  })

  test("falls back when randomUUID is unavailable", () => {
    setCrypto({})
    setSecure(true)
    setRandom(() => 0.5)
    expect(uuid()).toBe("8")
  })
})

import { ScopedKey, type ServerScope } from "@/utils/server-scope"

const normalize = (directory: string) => directory.replace(/[\\/]+$/, "")
const key = (scope: ServerScope, directory: string) => ScopedKey.from(scope, normalize(directory))

type State =
  | {
      status: "pending"
    }
  | {
      status: "ready"
    }
  | {
      status: "failed"
      message: string
    }

const state = new Map<string, State>()
const waiters = new Map<
  string,
  {
    promise: Promise<State>
    resolve: (state: State) => void
  }
>()

function deferred() {
  const box = { resolve: (_: State) => {} }
  const promise = new Promise<State>((resolve) => {
    box.resolve = resolve
  })
  return { promise, resolve: box.resolve }
}

export const Worktree = {
  get(scope: ServerScope, directory: string) {
    return state.get(key(scope, directory))
  },
  pending(scope: ServerScope, directory: string) {
    const id = key(scope, directory)
    const current = state.get(id)
    if (current && current.status !== "pending") return
    state.set(id, { status: "pending" })
  },
  ready(scope: ServerScope, directory: string) {
    const id = key(scope, directory)
    const next = { status: "ready" } as const
    state.set(id, next)
    const waiter = waiters.get(id)
    if (!waiter) return
    waiters.delete(id)
    waiter.resolve(next)
  },
  failed(scope: ServerScope, directory: string, message: string) {
    const id = key(scope, directory)
    const next = { status: "failed", message } as const
    state.set(id, next)
    const waiter = waiters.get(id)
    if (!waiter) return
    waiters.delete(id)
    waiter.resolve(next)
  },
  wait(scope: ServerScope, directory: string) {
    const id = key(scope, directory)
    const current = state.get(id)
    if (current && current.status !== "pending") return Promise.resolve(current)

    const existing = waiters.get(id)
    if (existing) return existing.promise

    const waiter = deferred()

    waiters.set(id, waiter)
    return waiter.promise
  },
}

import { describe, expect, test } from "bun:test"
import {
  addableProbePlan,
  addServerProbePlan,
  addServerViewModel,
  autoProbePlan,
  createProbeFailureGate,
  runAddableProbePlan,
  wslOpencodeAction,
  wslRuntimeRetryable,
} from "./settings-model"
import type { WslServersState } from "./types"

const readyWslState = readyState()

function readyState(input: Partial<WslServersState> = {}): WslServersState {
  return {
    runtime: { available: true, version: "2.4.13.0", error: null },
    installed: [],
    online: [],
    distroProbes: {},
    opencodeChecks: {},
    pendingRestart: false,
    servers: [],
    job: null,
    ...input,
  }
}

describe("WSL server settings presentation", () => {
  test("retries only settled unsuccessful runtimes", () => {
    expect(wslRuntimeRetryable({ kind: "starting" })).toBe(false)
    expect(wslRuntimeRetryable({ kind: "ready", url: "http://127.0.0.1:4096", username: null, password: null })).toBe(
      false,
    )
    expect(wslRuntimeRetryable({ kind: "failed", message: "boom" })).toBe(true)
    expect(wslRuntimeRetryable({ kind: "stopped" })).toBe(true)
  })

  test("offers install and update only when OpenCode needs attention", () => {
    expect(wslOpencodeAction(undefined)).toBeUndefined()
    expect(
      wslOpencodeAction({
        distro: "Debian",
        resolvedPath: null,
        version: null,
        expectedVersion: "1.2.3",
        matchesDesktop: null,
        error: null,
      }),
    ).toBe("wsl.onboarding.installOpencode")
    expect(
      wslOpencodeAction({
        distro: "Debian",
        resolvedPath: "/usr/local/bin/opencode",
        version: "1.2.2",
        expectedVersion: "1.2.3",
        matchesDesktop: false,
        error: null,
      }),
    ).toBe("wsl.onboarding.updateOpencode")
    expect(
      wslOpencodeAction({
        distro: "Debian",
        resolvedPath: "/usr/local/bin/opencode",
        version: "1.2.3",
        expectedVersion: "1.2.3",
        matchesDesktop: true,
        error: null,
      }),
    ).toBeUndefined()
  })

  test("plans addable distro probes with the selected distro first", () => {
    const plan = addableProbePlan({
      state: readyWslState,
      view: "main",
      adding: false,
      selectedDistro: "Ubuntu",
      addableInstalledDistros: [
        { name: "Debian", version: 2, isDefault: true },
        { name: "Ubuntu", version: 2, isDefault: false },
      ],
    })

    expect(plan?.key).toBe("distro:Ubuntu|distro:Debian")
    expect(plan?.distros).toEqual(["Ubuntu", "Debian"])
  })

  test("plans bootstrap probes for missing runtime and initial distro lists", () => {
    expect(autoProbePlan({ state: undefined, busy: false })).toBeUndefined()
    expect(autoProbePlan({ state: { ...readyWslState, runtime: null }, busy: false })).toEqual({
      key: "runtime",
      action: "probeRuntime",
    })
    expect(autoProbePlan({ state: readyWslState, busy: false })).toEqual({
      key: "distros",
      action: "refreshDistros",
    })
  })

  test("uses one command plan for bootstrap before addable distro probing", () => {
    expect(
      addServerProbePlan({
        state: { ...readyWslState, runtime: null },
        view: "main",
        adding: false,
        busy: false,
        selectedDistro: null,
        addableInstalledDistros: [{ name: "Debian", version: 2, isDefault: true }],
      }),
    ).toEqual({ kind: "auto", key: "auto:runtime", plan: { key: "runtime", action: "probeRuntime" } })

    expect(
      addServerProbePlan({
        state: {
          ...readyWslState,
          installed: [{ name: "Debian", version: 2, isDefault: true }],
          online: [{ name: "Ubuntu", label: "Ubuntu" }],
        },
        view: "main",
        adding: false,
        busy: false,
        selectedDistro: "Debian",
        addableInstalledDistros: [{ name: "Debian", version: 2, isDefault: true }],
      }),
    ).toEqual({ kind: "addable", key: "addable:distro:Debian", plan: { key: "distro:Debian", distros: ["Debian"] } })
  })

  test("does not accept the same failed probe command until reset", () => {
    const gate = createProbeFailureGate()

    expect(gate.accepts("addable:distro:Debian")).toBe(true)
    gate.settle("addable:distro:Debian", new Error("wsl failed"))
    expect(gate.accepts("addable:distro:Debian")).toBe(false)
    expect(gate.accepts("addable:distro:Ubuntu")).toBe(true)
    gate.reset()
    expect(gate.accepts("addable:distro:Debian")).toBe(true)
  })

  test("keeps default distro selection stable while probes resolve", () => {
    const model = addServerViewModel({
      state: {
        ...readyWslState,
        installed: [
          { name: "Debian", version: 2, isDefault: true },
          { name: "Ubuntu", version: 2, isDefault: false },
        ],
        online: [{ name: "Alpine", label: "Alpine Linux" }],
        distroProbes: {
          Ubuntu: { name: "Ubuntu", canExecute: true, hasBash: true, hasCurl: true, error: null },
        },
      },
      view: "main",
      selectedDistro: null,
      catalogSearch: "",
      catalogTarget: null,
      adding: false,
      probingAddable: false,
    })

    expect(model.selectedDistro).toBe("Debian")
  })

  test("keeps the dialog busy across serial addable probe job gaps", () => {
    const model = addServerViewModel({
      state: readyState({
        installed: [{ name: "Debian", version: 2, isDefault: true }],
        online: [{ name: "Ubuntu", label: "Ubuntu" }],
      }),
      view: "main",
      selectedDistro: null,
      catalogSearch: "",
      catalogTarget: null,
      adding: false,
      probingAddable: true,
    })

    expect(model.busy).toBe(true)
  })

  test("does not report ready when OpenCode is present but cannot run", () => {
    const model = addServerViewModel({
      state: {
        ...readyWslState,
        installed: [{ name: "Debian", version: 2, isDefault: true }],
        online: [{ name: "Ubuntu", label: "Ubuntu" }],
        distroProbes: {
          Debian: { name: "Debian", canExecute: true, hasBash: true, hasCurl: true, error: null },
        },
        opencodeChecks: {
          Debian: {
            distro: "Debian",
            resolvedPath: "/home/me/.opencode/bin/opencode",
            version: null,
            expectedVersion: "1.2.3",
            matchesDesktop: null,
            error: "opencode is installed but could not run",
          },
        },
      },
      view: "main",
      selectedDistro: null,
      catalogSearch: "",
      catalogTarget: null,
      adding: false,
      probingAddable: false,
    })

    expect(model.distroStatuses.Debian).toEqual({
      label: { key: "wsl.onboarding.installOpencode" },
      tone: "warning",
    })
    expect(model.primaryButton.action).toBe("install-opencode")
  })

  test("delegates addable probe plans to one batch command", async () => {
    const calls: string[][] = []

    await runAddableProbePlan({
      plan: { key: "distro:Debian|distro:Ubuntu", distros: ["Debian", "Ubuntu"] },
      api: {
        probeAddable: async (distros) => {
          calls.push(distros)
        },
      },
    })

    expect(calls).toEqual([["Debian", "Ubuntu"]])
  })
})

import * as Effect from "effect/Effect"
import * as Command from "effect/unstable/cli/Command"
import { Spec } from "./spec"
import { Daemon } from "../services/daemon"

export type Input<Value> =
  Value extends Spec.Node<infer _Name, infer Command, infer _Commands>
    ? Input<Command>
    : Value extends Command.Command<infer _Name, infer Input, infer _Context, infer _Error, infer _Requirements>
      ? Input
      : never

type RuntimeHandler = (input: unknown) => Effect.Effect<void, unknown, Daemon.Service>
type Loader<Node extends Spec.Any> = () => Promise<{
  default: (input: Input<Node>) => Effect.Effect<void, any, Daemon.Service>
}>
type ProvidedCommand = Command.Command<string, unknown, unknown, unknown, Daemon.Service>

export type Handlers<Node extends Spec.Any> = keyof Node["commands"] extends never
  ? Loader<Node>
  : { readonly $?: Loader<Node> } & { readonly [Key in keyof Node["commands"]]: Handlers<Node["commands"][Key]> }

interface LazyHandler {
  readonly spec: Command.Command.Any
  readonly load: () => Promise<{ default: RuntimeHandler }>
}

type RuntimeHandlers =
  | (() => Promise<{ default: RuntimeHandler }>)
  | {
      readonly $?: () => Promise<{ default: RuntimeHandler }>
      readonly [key: string]: RuntimeHandlers | (() => Promise<{ default: RuntimeHandler }>) | undefined
    }

export function handler<const Node extends Spec.Any, Error, Requirements>(
  _node: Node,
  run: (input: Input<Node>) => Effect.Effect<void, Error, Requirements>,
) {
  return run
}

export function handlers<const Root extends Spec.Any>(root: Root, handlers: Handlers<Root>) {
  const result: LazyHandler[] = []

  function add(node: Spec.Any, value: RuntimeHandlers) {
    if (typeof value === "function") {
      result.push({ spec: node.spec, load: value as () => Promise<{ default: RuntimeHandler }> })
      return
    }
    if (value.$) result.push({ spec: node.spec, load: value.$ as () => Promise<{ default: RuntimeHandler }> })
    for (const [name, child] of Object.entries(node.commands)) add(child, value[name] as RuntimeHandlers)
  }

  add(root, handlers as RuntimeHandlers)
  return result
}

export function run(commands: Spec.Any, handlers: ReadonlyArray<LazyHandler>, options: { readonly version: string }) {
  return Command.run(provide(commands, handlers), options) as Effect.Effect<void, unknown, Command.Environment>
}

function provide(node: Spec.Any, handlers: ReadonlyArray<LazyHandler>): ProvidedCommand {
  const handler = handlers.find((handler) => handler.spec === node.spec)
  const spec = handler
    ? node.spec.pipe(
        Command.withHandler((input) =>
          Effect.gen(function* () {
            yield* Effect.flatMap(Effect.promise(handler.load), (module) => module.default(input))
          }),
        ),
      )
    : node.spec
  if (!Object.keys(node.commands).length) return spec as ProvidedCommand
  return spec.pipe(
    Command.withSubcommands(Object.values(node.commands).map((child) => provide(child, handlers))),
  ) as ProvidedCommand
}

export * as Runtime from "./runtime"

import * as Command from "effect/unstable/cli/Command"

type Options<Config extends Command.Command.Config, Commands extends ReadonlyArray<Any>> = {
  readonly description?: string
  readonly params?: Config
  readonly commands?: Commands
}

export interface Node<
  Name extends string,
  Spec extends Command.Command<Name, any, any, any, any>,
  Commands extends Children,
> {
  readonly name: Name
  readonly spec: Spec
  readonly commands: Commands
}

export type Any = Node<string, Command.Command<any, any, any, any, any>, Children>
export type Children = Readonly<Record<string, Any>>

export function make<
  const Name extends string,
  const Config extends Command.Command.Config = {},
  const Commands extends ReadonlyArray<Any> = [],
>(name: Name, options: Options<Config, Commands> = {}) {
  const command = Command.make(name, options.params ?? ({} as Config))
  const spec = options.description ? command.pipe(Command.withDescription(options.description)) : command
  return {
    name,
    spec,
    commands: Object.fromEntries(
      (options.commands ?? []).map((command) => [command.name, command]),
    ) as ChildrenOf<Commands>,
  }
}

type ChildrenOf<Commands extends ReadonlyArray<Any>> = {
  readonly [Node in Commands[number] as Node["name"]]: Node
}

